import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)

    n = int(next(iterator))
    s = int(next(iterator))
    e = int(next(iterator))

    x = []
    for _ in range(n):
        x.append(int(next(iterator)))

    a = []
    for _ in range(n):
        a.append(int(next(iterator)))

    b = []
    for _ in range(n):
        b.append(int(next(iterator)))

    c = []
    for _ in range(n):
        c.append(int(next(iterator)))

    d = []
    for _ in range(n):
        d.append(int(next(iterator)))

    s -= 1
    e -= 1

    if s > e:
        s, e = e, s

    INF = float('inf')

    dp = [[INF, INF] for _ in range(n)]

    start_idx = s
    dp[start_idx][0] = 0
    dp[start_idx][1] = 0

    for l in range(s, -1, -1):
        for r in range(e, n):
            if l > r:
                break

            if l == r:
                if l == s:
                    continue
                else:
                    prev_l = l + 1
                    prev_r = l
                    cost_left = dp[prev_l][0]
                    cost_right = dp[prev_r][1]

                    if cost_left != INF:
                        dist = x[l] - x[l+1]
                        cost = cost_left + dist + c[l+1] + b[l]
                        if cost < dp[l][0]:
                            dp[l][0] = cost

                    if cost_right != INF:
                        dist = x[r] - x[r-1]
                        cost = cost_right + dist + d[r-1] + a[r]
                        if cost < dp[r][1]:
                            dp[r][1] = cost
                continue

            if l == s and r == e:
                continue

            current_dp_l0 = dp[l][0]
            current_dp_r1 = dp[r][1]

            if current_dp_l0 == INF and current_dp_r1 == INF:
                continue

            next_l = l - 1
            next_r = r + 1

            if next_l >= 0:
                dist = x[l] - x[next_l]
                cost = current_dp_l0 + dist + c[l] + b[next_l]
                if cost < dp[next_l][0]:
                    dp[next_l][0] = cost

            if next_r < n:
                dist = x[next_r] - x[r]
                cost = current_dp_r1 + dist + d[r] + a[next_r]
                if cost < dp[next_r][1]:
                    dp[next_r][1] = cost

            if next_l >= 0:
                dist = x[r] - x[next_l]
                cost = current_dp_r1 + dist + c[r] + b[next_l]
                if cost < dp[next_l][1]:
                    dp[next_l][1] = cost

            if next_r < n:
                dist = abs(x[next_r] - x[l])
                cost = current_dp_l0 + dist + d[l] + a[next_r]
                if cost < dp[next_r][0]:
                    dp[next_r][0] = cost

    ans = INF
    if dp[e][0] != INF:
        ans = min(ans, dp[e][0])
    if dp[e][1] != INF:
        ans = min(ans, dp[e][1])

    print(ans)

if __name__ == '__main__':
    solve()
